export const META = {};
for (const [id, [goal, points, sources, safety, description, extra]] of Object.entries(M)) {
  const m = { goal, points, sources: sources.map(k => SOURCES[k]) };
  if (safety) m.safety = safety;
  if (description) m.description = description;
  if (sources[0] && SOURCES[sources[0]]) m.url = SOURCES[sources[0]].url;
  if (VARIANTS[id]) m.variants = VARIANTS[id];
  Object.assign(m, extra || {});
  META[id] = m;
}

